# Let's try to construct a graph with girth >= 7
# We can try using the McGee graph (24 vertices, 3-regular, girth 7) as a base
# and add one more vertex

# First, let's try to build from scratch using a more sophisticated approach

import random
from collections import defaultdict

def has_short_cycle(edges, max_len=6):
    """Check if there's a cycle of length <= max_len"""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for start in range(25):
        # BFS limited depth
        visited = {start: 0}
        parent = {start: -1}
        queue = [start]
        while queue:
            v = queue.pop(0)
            if visited[v] >= max_len // 2:
                continue
            for nb in adj[v]:
                if nb not in visited:
                    visited[nb] = visited[v] + 1
                    parent[nb] = v
                    queue.append(nb)
                elif nb != parent[v] and visited[v] + visited[nb] + 1 <= max_len:
                    return True
    return False

def check_girth(edges):
    """Return the girth (shortest cycle length) or a large number if no cycle"""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    min_cycle = float('inf')
    for start in range(25):
        visited = {start: 0}
        parent = {start: -1}
        queue = [start]
        while queue:
            v = queue.pop(0)
            for nb in adj[v]:
                if nb not in visited:
                    visited[nb] = visited[v] + 1
                    parent[nb] = v
                    queue.append(nb)
                elif nb != parent[v]:
                    cycle_len = visited[v] + visited[nb] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

# Let's try a randomized construction with backtracking
def build_graph(seed=0):
    random.seed(seed)
    adj = defaultdict(set)
    edges = []

    # We'll try to add edges one by one
    # Order vertices by priority
    vertices = list(range(25))

    for iteration in range(10000):
        # Check if we have a valid graph
        degrees = [len(adj[v]) for v in range(25)]
        if all(3 <= d <= 6 for d in degrees):
            if not has_short_cycle(edges, 6):
                return edges
            else:
                # Try to fix by removing some edges
                pass

        # Find vertices that need more edges
        under = [v for v in range(25) if len(adj[v]) < 3]
        if under:
            v = random.choice(under)
        else:
            # All have at least 3, find one with < 6
            candidates = [v for v in range(25) if len(adj[v]) < 6]
            if not candidates:
                break
            v = random.choice(candidates)

        # Find possible neighbors
        possible = []
        for u in range(25):
            if u == v or u in adj[v]:
                continue
            if len(adj[u]) >= 6:
                continue
            # Check if adding edge creates short cycle
            test_edges = edges + [(min(v,u), max(v,u))]
            if not has_short_cycle(test_edges, 6):
                possible.append(u)

        if not possible:
            # Backtrack: remove some edges
            if edges:
                # Remove a random edge
                idx = random.randint(0, len(edges)-1)
                e = edges.pop(idx)
                adj[e[0]].discard(e[1])
                adj[e[1]].discard(e[0])
            continue

        u = random.choice(possible)
        edges.append((min(v,u), max(v,u)))
        adj[v].add(u)
        adj[u].add(v)

    return None

for seed in range(100):
    result = build_graph(seed)
    if result:
        print(f"Found with seed {seed}: {len(result)} edges")
        deg = [0]*25
        for u,v in result:
            deg[u] += 1
            deg[v] += 1
        print("Degrees:", deg)
        print("Girth:", check_girth(result))
        break
else:
    print("Not found in 100 tries")
